import logging

from ute_common_converter.to_number import to_int
from ute_common_converter.to_bool import to_bool

from .common import WTSCommonInterface
from ..wts.state_machine import WTSStateMachine


class WTSEgateInterface(WTSCommonInterface):

    def setup_egate(self, egate_port, host_ip='127.0.0.1', tool_dir=None, save_egate=False, **kwargs):
        """Setup WTSSIM library to work with egate.

        Library will be configured to work through:

        * SSH connection to start/stop egate services.
        * Telnet connection to execute egate commands.

        :param integer egate_port: Egate process port.
        :param string  host_ip:    IP Address of the remote machine.
        :param string  tool_dir:   Path to the directory where egate binary is available.
        :param boolean save_egate: Prevents tearing down of egate if set to True provided that teardown keywords are not used.
                                   Default value is False. This parameter is used in conjunction with reconnect flag on
                                   start_egate_process keyword. save_egate parameter must be set to True if user wants to
                                   reconnect to a running egate instance.

        |

        :Supported SSH parameters are available via kwargs:
            * **ssh_user**   (string)  - Username for SSH authentication. Default is 'ute'.
            * **ssh_pass**   (string)  - Password for SSH authentication. Default is 'ute'.
            * **ssh_port**   (integer) - SSH service port on specified machine. Default is 22.
            * **ssh_prompt** (string)  - SH prompt received after logging in. Default is '$ '.


        It is possible to change kwargs parameters by using syntax like in example below:
        ::

            Setup egate     ssh_user=test_user    ssh_pass=test_pass    ssh_port=22    ssh_prompt=\$

        :More parameters supported via kwargs:
            * **ext** (string) - Extension library or extension class.
        """
        self.save_egate = to_bool(save_egate)

        if self.save_egate:
            logging.warn("\'save_egate\' flag is set. Egate will not terminate after test execution "
                         "unless overriden with Teardown keywords.")

        alias = kwargs.get('alias')
        connection_settings = self._configure_ssh_connection(host_ip,
                                                             kwargs.get('ssh_user'),
                                                             kwargs.get('ssh_pass'),
                                                             kwargs.get('ssh_port'),
                                                             kwargs.get('ssh_prompt'))
        ssh_client = self._create_ssh_client_from_settings(connection_settings)
        telnet_client = self._create_telnet_client_from_settings(connection_settings, egate_port)
        egate = self._create_egate(egate_port, ssh_client, telnet_client, tool_dir)
        self._notify_extenders(egate, alias, kwargs.get('ext', []))
        self._store_egate(egate, alias)

    def start_egate_process(self, cfg_file=None, suite_file=None, timeout=None, retry=0, **kwargs):
        """Start an egate process and configure it.

        :param string  cfg_file:   Path to the lua file where egate configuration is stored.
        :param timeout:            Timeout for the configuration operation. Default is 60 seconds.
                                   Can be specified in human format like 5s, 10minutes, 1min 5s.
        :param string  suite_file: Path or name of suite file which will be provided for egate process.
        :param int retry:          Number of times the user want to retry the process.


        :More parameters supported via kwargs:
            * **reconnect** (bool) - Allows user to reconnect to an existing egate instance. Reconnect
                                     parameter connects to an egate instance if there is a manually created
                                     egate or if save_egate parameter in setup_egate keyword is set.
                                     Default value is False.
        """
        alias = kwargs.get('alias')
        timeout = self._to_secs(timeout)
        wts = self.wts_store.get(alias)
        wts.set_egate_params(cfg_file, suite_file, timeout, retry)

        if to_bool(kwargs.get('reconnect', False)):
            if wts.egates[0].is_running:
                wts.reconnect()
            else:
                logging.warn("UNABLE TO RECONNECT TO EGATE: No egate found in port {}.\n"
                             "Creating new egate process...".format(wts.egates[0].port))
                wts.start()
        else:
            wts.start()

    def link_edaemons_to_egate(self, *edaemons_aliases, **kwargs):
        """Connect configured edaemons with egate to have stable edaemon/egate startup.

        :param edaemons_aliases: One or more edaemon aliases to add to egate. Please use **default** for edaemon if
                                 the alias parameter was not specified during the edaemon setup.

        :note: Egate has a startup procedure which enables starting egate and edaemon in a defined order. It is critical to stop
               the egate process before the edaemon processes and not to stop/start edaemons while egate is working
               (otherwise egate and edaemon may crash).
        """
        alias = kwargs.get('alias')
        for edaemon_alias in edaemons_aliases:
            egate = self.wts_store.get(alias).egates[0]
            edaemon = self.edaemon_store.get(edaemon_alias).edaemons[0]
            egate.add_edaemon(edaemon)

    def start_egate_services(self, timeout=None, retry=0, check_version=True, **kwargs):
        """Configure and start egate services like MME, UEC, ENB.

        :param timeout: Timeout for the start operation. Default is 180 seconds.
                        Can be specified in human format like 5s, 10minutes, 1min 5s.
        :param retry: Number of times the user want to retry start_services. may not be applicable if eNB is already in
                                        ACTIVE state
        :param check_version: Enable/Disable version checking between WTS binaries.


        """
        timeout = self._to_secs(timeout)
        alias = kwargs.get('alias')
        egate = self.wts_store.get(alias).egates[0]
        retry = to_int(retry)
        if retry <= 0:
            egate.start_services(timeout, check_version)
        if retry > 0:
            egate.retry_services(timeout, retry, check_version)

    def add_egate_lua_dirs(self, *lua_dirs, **kwargs):
        """Add one or more paths to the list of directories where lua scripts are stored.

        :param list lua_dirs: One or more directory paths where lua scripts are stored.

        :note: This option is useful to define custom directories where lua scripts are stored. This keyword has to
               executed before start_egate_process keyword.


        """
        alias = kwargs.get('alias')
        egate = self.wts_store.get(alias).egates[0]
        for each in lua_dirs:
            egate.lua_dirs.append(each)

    def teardown_egate(self, **kwargs):
        """Stops and removes connection of egate.

        :note: Teardown for keyword "Setup Egate", does not teardown edaemon and wts applications.


        """
        alias = kwargs.get('alias')
        self.wts_store.get(alias).stop()
        self.wts_store.get(alias).close_all_connections()
        self.wts_store.remove(alias)
        self.notifier.egate_deleted(alias)

    def teardown_all_aliases_for_egate(self, **kwargs):
        """Stops and removes connection of all aliases of egate and collects their log files

        :note:Does not teardown edaemon and wts applications

        """
        for alias_name_wts in self.wts_store.aliases:
            self.collect_egate_log_files(alias=alias_name_wts)
            self.teardown_egate(alias=alias_name_wts)

    def collect_egate_log_files(self, unzip=None, subdirectory=None, **kwargs):
        """Download created files to the test result directory.

        :param boolean unzip:        Flag indicating whether collected logs should be extracted.
        :param string  subdirectory: Name of folder to create in addition to the normal test result structure.

        |

        :Supported SSH parameters are available via kwargs:
            * **ssh_user**   (string)  - Username for SSH authentication. Default is 'ute'.
            * **ssh_pass**   (string)  - Password for SSH authentication. Default is 'ute'.
            * **ssh_port**   (integer) - SSH service port on specified machine. Default is 22.
            * **ssh_prompt** (string)  - SH prompt received after logging in. Default is '$ '.

        It is possible to change kwargs parameters by using syntax like in example below:
        ::

            Some keyword     ssh_user=test_user    ssh_pass=test_pass    ssh_port=22    ssh_prompt=\$

        This method will download the following files:

        * egate.log
        * egate_console.log


        :note: Format of result directory structure is: TestSuite1/TestSuite2/TestCase/SubFolder.
        """
        alias = kwargs.get('alias')
        wts = self.wts_store.get(alias)
        self._collect_logs(wts, unzip, subdirectory)

    def execute_egate_command(self, cmd, pass_regexp=None, fail_regexp=None, timeout=None, **kwargs):
        """Execute a command on egate.

        :param string  cmd: Command to execute.
        :param string  pass_regexp: Regexp indicating that the command passed.
        :param string  fail_regexp: Regexp indicating that the command failed.
        :param timeout: Timeout for this operation. Default is 10 seconds.
                        Can be specified in human format like 5s, 10minutes, 1min 5s.

        |

        :Supported parameter is available via kwargs:
            * **return_output**   (boolean)  - Flag indicating whether egate log should be printed out. Default is True.
            * **padding_buffer**  (int)      - Parameter setting the size of the padding buffer to be used in the output
                                               If RRC protocol is enabled, set value >40000
       It is possible to change kwargs parameters by using syntax like in example below:
        ::

            Execute egate command     return_output=True

        :return: Data from command execution.
        :rtype: string
        """
        alias = kwargs.get('alias')
        return_output = kwargs.get('return_output', True)
        timeout = self._to_secs(timeout)
        egate = self.wts_store.get(alias).egates[0]
        padding_buffer = kwargs.get("padding_buffer", 5000)
        return egate.execute_telnet_command(cmd=cmd,
                                            return_output=return_output,
                                            pass_regexp=pass_regexp,
                                            fail_regexp=fail_regexp,
                                            timeout=timeout,
                                            padding_buffer=padding_buffer)

    def execute_egate_command_and_wait_for_data(self, cmd, timeout=None, **kwargs):
        """Execute a command on egate and wait for data from the command.

        Many Egate commands are asynchronous. Because of that the data may appear later. This method will execute
        provided command and will wait until some data appears - will ignore any prompt before data.

        :param string  cmd: Command to execute.
        :param timeout: Timeout for this operation. Default is 10 seconds.
                        Can be specified in human format like 5s, 10minutes, 1min 5s.

        |

        :Supported parameter is available via kwargs:
            * **return_output**   (boolean)  - Flag indicating whether egate log should be printed out. Default is True.
            * **pass_regexp**     (string)   - Regexp indicating that the command passed.
            * **fail_regexp**     (string)   - Regexp indicating that the command failed.

        It is possible to change kwargs parameters by using syntax like in example below:
        ::

            Execute egate command and wait for data     return_output=True, pass_regexp='EGATE>'


        :return: Data from command execution.
        :rtype: string
        """
        alias = kwargs.get('alias')
        return_output = kwargs.get('return_output', True)
        pass_regexp = kwargs.get('pass_regexp', 'EGATE>')
        fail_regexp = kwargs.get('fail_regexp')
        timeout = self._to_secs(timeout)
        egate = self.wts_store.get(alias).egates[0]
        return egate.execute_telnet_command(cmd=cmd,
                                            return_output=return_output,
                                            pass_regexp=pass_regexp,
                                            fail_regexp=fail_regexp,
                                            timeout=timeout,
                                            ignore_prompt_prefix=True)

    def _store_egate(self, egate, alias):
        wts = WTSStateMachine(alias=alias)
        wts.add_egate(egate)
        self.wts_store.add(wts, alias)
